func streamLocations(to channel: TripChannel) async throws {
    for try await update in CLLocationUpdate.liveUpdates(.automotiveNavigation) {
        guard let loc = update.location else { continue }
        try await channel.send(.location(lat: loc.coordinate.latitude,
                                          lng: loc.coordinate.longitude,
                                          bearing: loc.course, at: loc.timestamp))
    }
}
